library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Sex value mapping function
map_sex <- function(x) {
  x <- as.integer(x)
  ifelse(x %in% c(1L, 2L), x, NA_integer_)
}

# Create sex variable using most recent valid response first
sex <- rep(NA_integer_, nrow(wave_one_lsype_young_person_2020))

# Check W9DSEX (wave9, age 32) first
sex[!is.na(wave_ns9_2022_main_interview$W9DSEX) & wave_ns9_2022_main_interview$W9DSEX %in% c(1, 2)] <- map_sex(wave_ns9_2022_main_interview$W9DSEX)[!is.na(wave_ns9_2022_main_interview$W9DSEX) & wave_ns9_2022_main_interview$W9DSEX %in% c(1, 2)]

# Fallback through earlier waves in reverse order
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_ns8_2015_main_interview$W8CMSEX)[!is.na(wave_ns8_2015_main_interview$W8CMSEX) & wave_ns8_2015_main_interview$W8CMSEX %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_seven_lsype_young_person_2020$W7Sex)[!is.na(wave_seven_lsype_young_person_2020$W7Sex) & wave_seven_lsype_young_person_2020$W7Sex %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_six_lsype_young_person_2020$W6Sex)[!is.na(wave_six_lsype_young_person_2020$W6Sex) & wave_six_lsype_young_person_2020$W6Sex %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_five_lsype_young_person_2020$W5SexYP)[!is.na(wave_five_lsype_young_person_2020$W5SexYP) & wave_five_lsype_young_person_2020$W5SexYP %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_four_lsype_young_person_2020$W4SexYP)[!is.na(wave_four_lsype_young_person_2020$W4SexYP) & wave_four_lsype_young_person_2020$W4SexYP %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_three_lsype_young_person_2020$W3sexYP)[!is.na(wave_three_lsype_young_person_2020$W3sexYP) & wave_three_lsype_young_person_2020$W3sexYP %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_two_lsype_young_person_2020$W2SexYP)[!is.na(wave_two_lsype_young_person_2020$W2SexYP) & wave_two_lsype_young_person_2020$W2SexYP %in% c(1, 2)]
}
if (any(is.na(sex))) {
  sex <- sex | map_sex(wave_one_lsype_young_person_2020$W1sexYP)[!is.na(wave_one_lsype_young_person_2020$W1sexYP) & wave_one_lsype_young_person_2020$W1sexYP %in% c(1, 2)]
}

# Write output
write_csv(wave_one_lsype_young_person_2020 %>% right_join(wave_two_lsype_young_person_2020, by = "NSID") %>% right_join(wave_three_lsype_young_person_2020, by = "NSID") %>% right_join(wave_four_lsype_young_person_2020, by = "NSID") %>% right_join(wave_five_lsype_young_person_2020, by = "NSID") %>% right_join(wave_six_lsype_young_person_2020, by = "NSID") %>% right_join(wave_seven_lsype_young_person_2020, by = "NSID") %>% right_join(wave_ns8_2015_main_interview, by = "NSID") %>% right_join(wave_ns9_2022_main_interview, by = "NSID") %>% select(NSID, sex), "data/output/cleaned_data.csv")

